/**
 * Emit 千鳥格子's cold-clear self-play artefact (`cutcopy-selfplay.ts`). This file is argv and file IO only.
 *
 *   bun pipeline/sim/emit-cutcopy-selfplay.ts --games games-40k.jsonl --coach-seed 0 --out analysis/cutcopy-selfplay.json
 *       scan every game of a cc-coach COACH_MODE=selfplay JSONL, commit the games holding a hit, build
 *   bun pipeline/sim/emit-cutcopy-selfplay.ts --rebuild --out analysis/cutcopy-selfplay.json
 *       build again from the committed artefact's own placements (what the test does; byte for byte)
 *
 * The JSONL is regenerated by the commands in tools/cc-coach/FINDINGS-cutcopy-selfplay.md (cold-clear at the
 * pinned rev, the patch, the harness, CC_NODES and COACH_SEED as recorded in the artefact's provenance).
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { BOT, SELFPLAY_PATH, build, rebuild, scan, select, serialise } from './cutcopy-selfplay.ts';

if (import.meta.main) {
  const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
  const t0 = performance.now();
  let out: any;
  if (process.argv.includes('--rebuild')) {
    out = rebuild(JSON.parse(readFileSync(SELFPLAY_PATH, 'utf8')));
  } else {
    const path = arg('--games'), seed = arg('--coach-seed');
    if (!path || seed === undefined) throw new Error('usage: --games <selfplay.jsonl> --coach-seed <n> [--out f] | --rebuild [--out f]');
    const text = readFileSync(path, 'utf8');
    const games = text.split('\n').filter(l => l.trim()).map(l => JSON.parse(l));
    const { summary, replayed } = scan(games);
    console.error(`scanned ${summary.games} games, ${summary.hits.length} hits, ${((performance.now() - t0) / 1000).toFixed(1)} s`);
    const provenance = { ...BOT, cc_nodes: summary.cc_nodes, coach_seed: Number(seed),
                         games_jsonl_md5: createHash('md5').update(text).digest('hex'),
                         games_jsonl_note: 'the bot\'s whole output, not committed; regenerate it with the commands in '
                           + 'tools/cc-coach/FINDINGS-cutcopy-selfplay.md and re-run this emitter to re-derive `scan`' };
    out = build(provenance, summary, select(games, summary, replayed));
  }
  const text = serialise(out);
  const o = arg('--out');
  if (o) writeFileSync(o, text); else process.stdout.write(text);
  console.error(`${out.games.length} games, ${text.length} bytes, ${((performance.now() - t0) / 1000).toFixed(1)} s`);
}
